import 'dart:io';import 'package:file_picker/file_picker.dart';import 'package:path/path.dart' as p;import 'package:path_provider/path_provider.dart';
class LocalAttachmentService{
 Future<String?> pickAndStore({List<String> extensions=const ['jpg','jpeg','png','pdf'],int maxBytes=10*1024*1024})async{final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:extensions,withData:false);if(result==null||result.files.single.path==null)return null;final source=File(result.files.single.path!);final size=await source.length();if(size>maxBytes)throw Exception('Choose a file smaller than ${(maxBytes/1024/1024).round()} MB.');final root=await getApplicationDocumentsDirectory();final dir=Directory(p.join(root.path,'pawpal','attachments'));await dir.create(recursive:true);final ext=p.extension(source.path).toLowerCase();final target=p.join(dir.path,'${DateTime.now().microsecondsSinceEpoch}$ext');await source.copy(target);return target;}
 Future<String> storePath(String sourcePath,{int maxBytes=10*1024*1024})async{final source=File(sourcePath);final size=await source.length();if(size>maxBytes)throw Exception('File exceeds the 10 MB attachment limit.');final root=await getApplicationDocumentsDirectory();final dir=Directory(p.join(root.path,'pawpal','attachments'));await dir.create(recursive:true);final ext=p.extension(source.path).toLowerCase();final target=p.join(dir.path,'${DateTime.now().microsecondsSinceEpoch}$ext');await source.copy(target);return target;}\n Future<void> clearAll()async{final root=await getApplicationDocumentsDirectory();final dir=Directory(p.join(root.path,'pawpal','attachments'));if(await dir.exists())await dir.delete(recursive:true);}\n Future<void> delete(String path)async{final file=File(path);if(await file.exists())await file.delete();}
}
